
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_cc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_cc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.180998796928750e-01, -1.175098655897358e-01, -1.166632982014776e-01, -1.154500632112331e-01, -1.137144188422297e-01, -1.112379422812861e-01, -1.077182242196056e-01, -1.027451292029404e-01, -9.578094768898122e-02, -8.609784447791136e-02, -7.180811557052395e-02, -5.832533554238101e-02, -5.312509445685303e-02, -4.356367876982232e-02, -3.280996957020003e-02, -2.046953878415961e-02, -9.021986680515633e-03, -2.246095801171577e-03, -2.520240917546058e-04, -1.115118374117174e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


